'use client';

import * as React from 'react';
import { Dialog as BaseDialog } from '@base-ui/react/dialog';
import { Surface, type SurfaceMaterial, type SurfaceRadius } from '../surface/surface';
import './dialog.css';

/* DIALOG: a modal layer on Base UI Dialog. A scrim behind a surface near the top of the viewport;
 * it rises a step on the surface spring and closes on release. Focus stays inside; Escape and a
 * click outside close it. Slots: Dialog.Root, Dialog.Popup. */

export interface DialogRootProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  children: React.ReactNode;
}

function Root({ open, onOpenChange, children }: DialogRootProps) {
  return (
    <BaseDialog.Root open={open} onOpenChange={(o) => onOpenChange(o)}>
      <BaseDialog.Portal>
        <BaseDialog.Backdrop className="mu-dialog-scrim" />
        {children}
      </BaseDialog.Portal>
    </BaseDialog.Root>
  );
}

export interface DialogPopupProps extends React.HTMLAttributes<HTMLDivElement> {
  material?: SurfaceMaterial;
  radius?: SurfaceRadius;
  'aria-label'?: string;
}

function Popup({ material = 'plate', radius = 'card', className, children, ...props }: DialogPopupProps) {
  return (
    <BaseDialog.Popup className={className ? `mu-dialog ${className}` : 'mu-dialog'} aria-label={props['aria-label']} render={<Surface material={material} radius={radius} />}>
      {children}
    </BaseDialog.Popup>
  );
}

export const Dialog = Object.assign(Root, { Root, Popup });

@import "../tokens.css";

/* Dialog: a scrim behind a surface. Its look is the dialog recipe (--mu-r-dialog-*) and the surface. */
.mu-dialog-scrim {
  position: fixed;
  inset: var(--mu-zero);
  z-index: var(--mu-r-dialog-scrim-z);
  background: var(--mu-r-dialog-scrim-color);
  transition: opacity var(--mu-spring-surface-d) var(--mu-spring-surface);
}
.mu-dialog-scrim:is([data-starting-style], [data-ending-style]) { opacity: var(--mu-zero); }
.mu-dialog {
  position: fixed;
  z-index: var(--mu-r-dialog-scrim-z);
  top: var(--mu-r-dialog-self-top);
  left: 50%;
  translate: -50% var(--mu-zero);
  outline: var(--mu-zero);
  transition:
    opacity var(--mu-spring-surface-d) var(--mu-spring-surface),
    transform var(--mu-spring-surface-d) var(--mu-spring-surface);
}
.mu-dialog:is([data-starting-style], [data-ending-style]) {
  opacity: var(--mu-zero);
  transform: translateY(calc(var(--mu-r-dialog-self-enter-y) * var(--mu-travel-surface))) scale(calc(1 - (1 - var(--mu-r-dialog-self-enter-scale)) * var(--mu-travel-surface)));
}
.mu-dialog[data-ending-style] { transition-duration: var(--mu-spring-release-d); transition-timing-function: var(--mu-spring-release); }
